23	// disconnectedOnce ensures the disconnection warning runs at most once per process.
24	var disconnectedOnce sync.Once //nolint:gochecknoglobals // intentional per-process gate
25	
26	// IsMetadataDisconnected checks whether local and remote entire/checkpoints/v1
27	// branches exist but share no common ancestor (the "empty-orphan bug").
28	// Returns (false, nil) if either branch is missing, they point to the same hash,
29	// or they share a common ancestor (normal divergence handled by push merge).
30	// Returns (true, nil) only when both exist and are truly disconnected.
31	func IsMetadataDisconnected(ctx context.Context, repo *git.Repository) (bool, error) {
32		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
33		localRef, err := repo.Reference(refName, true)
34		if errors.Is(err, plumbing.ErrReferenceNotFound) {
35			return false, nil
36		}
37		if err != nil {
38			return false, fmt.Errorf("failed to check local metadata branch: %w", err)
39		}
40	
41		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
42		remoteRef, err := repo.Reference(remoteRefName, true)
43		if errors.Is(err, plumbing.ErrReferenceNotFound) {
44			return false, nil
45		}
46		if err != nil {
47			return false, fmt.Errorf("failed to check remote metadata branch: %w", err)
48		}
49	
50		if localRef.Hash() == remoteRef.Hash() {
51			return false, nil
52		}
53	
54		repoPath, err := getRepoPath(repo)
55		if err != nil {
56			return false, err
57		}
58	
59		return isDisconnected(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
60	}
