373	// getRepoPath returns the filesystem path for the repository's worktree.
374	func getRepoPath(repo *git.Repository) (string, error) {
375		wt, err := repo.Worktree()
376		if err != nil {
377			return "", fmt.Errorf("failed to get worktree: %w", err)
378		}
379		return wt.Filesystem.Root(), nil
380	}
