23	func TestReconcileDisconnected_NoRemote(t *testing.T) {
24		t.Parallel()
25	
26		// Local-only repo with metadata branch, no remote tracking branch
27		tmpDir := t.TempDir()
28		run := func(args ...string) {
29			cmd := exec.CommandContext(context.Background(), "git", args...)
30			cmd.Dir = tmpDir
31			if out, err := cmd.CombinedOutput(); err != nil {
32				t.Fatalf("git %v failed: %v\n%s", args, err, out)
33			}
34		}
35		run("init", "-b", "main")
36		run("config", "user.email", "test@test.com")
37		run("config", "user.name", "Test User")
38		run("config", "commit.gpgsign", "false")
39		if err := os.WriteFile(filepath.Join(tmpDir, "README.md"), []byte("# Test"), 0o644); err != nil {
40			t.Fatalf("failed to write: %v", err)
41		}
42		run("add", ".")
43		run("commit", "-m", "init")
44	
45		// Create orphan metadata branch
46		run("checkout", "--orphan", paths.MetadataBranchName)
47		run("rm", "-rf", ".")
48		if err := os.WriteFile(filepath.Join(tmpDir, "metadata.json"), []byte(`{"test":true}`), 0o644); err != nil {
49			t.Fatalf("failed to write: %v", err)
50		}
51		run("add", ".")
52		run("commit", "-m", "checkpoint")
53		run("checkout", "main")
54	
55		repo, err := git.PlainOpen(tmpDir)
56		if err != nil {
57			t.Fatalf("failed to open repo: %v", err)
58		}
59	
60		// Should be a no-op (no remote)
61		if err := ReconcileDisconnectedMetadataBranch(context.Background(), repo, io.Discard); err != nil {
62			t.Fatalf("unexpected error: %v", err)
63		}
64	}
