147	func TestReconcileDisconnected_Disconnected(t *testing.T) {
148		t.Parallel()
149	
150		bareDir := initBareWithMetadataBranch(t)
151		cloneDir, run := cloneWithConfig(t, bareDir)
152	
153		// Create a disconnected local metadata branch (simulating the empty-orphan bug)
154		run("checkout", "--orphan", "temp-orphan")
155		run("rm", "-rf", ".")
156		localDir := filepath.Join(cloneDir, "ab", "cdef012345")
157		if err := os.MkdirAll(localDir, 0o755); err != nil {
158			t.Fatalf("failed to create dir: %v", err)
159		}
160		if err := os.WriteFile(filepath.Join(localDir, "metadata.json"), []byte(`{"checkpoint_id":"abcdef012345"}`), 0o644); err != nil {
161			t.Fatalf("failed to write: %v", err)
162		}
163		run("add", ".")
164		run("commit", "-m", "Checkpoint: abcdef012345")
165		run("branch", "-f", paths.MetadataBranchName, "temp-orphan")
166		run("checkout", "main")
167	
168		repo, err := git.PlainOpen(cloneDir)
169		if err != nil {
170			t.Fatalf("failed to open repo: %v", err)
171		}
172	
173		// Verify they are disconnected before reconcile
174		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
175		localRef, err := repo.Reference(refName, true)
176		if err != nil {
177			t.Fatalf("local ref not found: %v", err)
178		}
179		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
180		remoteRef, err := repo.Reference(remoteRefName, true)
181		if err != nil {
182			t.Fatalf("remote ref not found: %v", err)
183		}
184		if localRef.Hash() == remoteRef.Hash() {
185			t.Fatal("expected different hashes before reconcile")
186		}
187	
188		// Run reconciliation
189		if err := ReconcileDisconnectedMetadataBranch(context.Background(), repo, io.Discard); err != nil {
190			t.Fatalf("ReconcileDisconnectedMetadataBranch() failed: %v", err)
191		}
192	
193		// Verify result
194		newRef, err := repo.Reference(refName, true)
195		if err != nil {
196			t.Fatalf("local ref not found after reconcile: %v", err)
197		}
198	
199		// Should have linear history: new tip -> remote tip -> remote root
200		tipCommit, err := repo.CommitObject(newRef.Hash())
201		if err != nil {
202			t.Fatalf("failed to get tip commit: %v", err)
203		}
204	
205		// Tip's parent should be the remote tip (linear chain, not merge)
206		if len(tipCommit.ParentHashes) != 1 {
207			t.Fatalf("expected 1 parent (linear), got %d", len(tipCommit.ParentHashes))
208		}
209		if tipCommit.ParentHashes[0] != remoteRef.Hash() {
210			t.Errorf("tip parent = %s, want remote tip %s", tipCommit.ParentHashes[0], remoteRef.Hash())
