628	// TestCollectCommitChain_DepthLimit verifies that collectCommitChain returns an error
629	// when the commit chain exceeds MaxCommitTraversalDepth without reaching a root commit.
630	func TestCollectCommitChain_DepthLimit(t *testing.T) {
631		t.Parallel()
632	
633		dir := t.TempDir()
634		repo, err := git.PlainInit(dir, false)
635		require.NoError(t, err)
636	
637		// Create an empty tree for all commits.
638		emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
639		treeObj := repo.Storer.NewEncodedObject()
640		require.NoError(t, emptyTree.Encode(treeObj))
641		treeHash, err := repo.Storer.SetEncodedObject(treeObj)
642		require.NoError(t, err)
643	
644		// Build a linear chain of MaxCommitTraversalDepth+1 commits (all have parents,
645		// so none is a root). collectCommitChain should bail out at the depth limit.
646		var tip plumbing.Hash
647		for i := range MaxCommitTraversalDepth + 1 {
648			c := &object.Commit{
649				TreeHash:  treeHash,
650				Author:    object.Signature{Name: "test", Email: "test@test.com", When: time.Now().Add(time.Duration(i) * time.Second)},
651				Committer: object.Signature{Name: "test", Email: "test@test.com", When: time.Now().Add(time.Duration(i) * time.Second)},
652				Message:   "commit\n",
653			}
654			if tip != plumbing.ZeroHash {
655				c.ParentHashes = []plumbing.Hash{tip}
656			}
657			obj := repo.Storer.NewEncodedObject()
658			require.NoError(t, c.Encode(obj))
659			h, sErr := repo.Storer.SetEncodedObject(obj)
660			require.NoError(t, sErr)
661			tip = h
662		}
663	
664		_, err = collectCommitChain(repo, tip)
665		require.Error(t, err)
666		assert.Contains(t, err.Error(), "exceeded")
667		assert.Contains(t, err.Error(), "without reaching root")
668	}
