236	// handleRotationConflict handles the case where remote /full/current was rotated.
237	// Merges local /full/current into the latest remote archived generation to avoid
238	// duplicating checkpoint data, then adopts remote's /full/current as local.
239	func handleRotationConflict(ctx context.Context, target string, repo *git.Repository, refName, tmpRefName plumbing.ReferenceName, remoteOnlyArchives []string) error {
240		// Use the latest remote-only archive
241		latestArchive := remoteOnlyArchives[len(remoteOnlyArchives)-1]
242		archiveRefName := plumbing.ReferenceName(paths.V2FullRefPrefix + latestArchive)
243	
244		// Fetch the latest archived generation
245		archiveTmpRef := plumbing.ReferenceName("refs/entire-fetch-tmp/archive-" + latestArchive)
246		archiveRefSpec := fmt.Sprintf("+%s:%s", archiveRefName, archiveTmpRef)
247		fetchCmd := CheckpointGitCommand(ctx, target, "fetch", target, archiveRefSpec)
248		fetchCmd.Env = append(fetchCmd.Env, "GIT_TERMINAL_PROMPT=0")
249		if output, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
250			return fmt.Errorf("fetch archived generation failed: %s", output)
251		}
252		defer func() {
253			_ = repo.Storer.RemoveReference(archiveTmpRef) //nolint:errcheck // cleanup is best-effort
254		}()
255	
256		// Get archived generation state
257		archiveRef, err := repo.Reference(archiveTmpRef, true)
258		if err != nil {
259			return fmt.Errorf("failed to get archived ref: %w", err)
260		}
261		archiveCommit, err := repo.CommitObject(archiveRef.Hash())
262		if err != nil {
263			return fmt.Errorf("failed to get archive commit: %w", err)
264		}
265		archiveTree, err := archiveCommit.Tree()
266		if err != nil {
267			return fmt.Errorf("failed to get archive tree: %w", err)
268		}
269	
270		// Get local /full/current state
271		localRef, err := repo.Reference(refName, true)
272		if err != nil {
273			return fmt.Errorf("failed to get local ref: %w", err)
274		}
275		localCommit, err := repo.CommitObject(localRef.Hash())
276		if err != nil {
277			return fmt.Errorf("failed to get local commit: %w", err)
278		}
279		localTree, err := localCommit.Tree()
280		if err != nil {
281			return fmt.Errorf("failed to get local tree: %w", err)
282		}
283	
284		// Tree-merge local /full/current into archived generation.
285		// Git content-addressing deduplicates shared shard paths automatically.
286		entries := make(map[string]object.TreeEntry)
287		if err := checkpoint.FlattenTree(repo, archiveTree, "", entries); err != nil {
288			return fmt.Errorf("failed to flatten archive tree: %w", err)
289		}
290		if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
291			return fmt.Errorf("failed to flatten local tree: %w", err)
292		}
293	
294		// Update generation.json timestamps if present in the merged tree.
295		// Use the local /full/current HEAD commit time as the newest checkpoint time
296		// (more accurate than time.Now() for cleanup scheduling).
297		if genEntry, exists := entries[paths.GenerationFileName]; exists {
298			if updatedEntry, updateErr := updateGenerationTimestamps(repo, genEntry.Hash, localCommit.Committer.When.UTC()); updateErr == nil {
299				entries[paths.GenerationFileName] = updatedEntry
300			} else {
301				logging.Warn(ctx, "rotation recovery: failed to update generation timestamps, using stale values",
302					slog.String("error", updateErr.Error()),
303				)
304			}
305		}
306	
307		mergedTreeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
308		if err != nil {
309			return fmt.Errorf("failed to build merged tree: %w", err)
310		}
311	
312		// Create commit parented on archive's commit (fast-forward)
313		mergeCommitHash, err := createMergeCommitCommon(repo, mergedTreeHash,
314			[]plumbing.Hash{archiveRef.Hash()},
315			"Merge local checkpoints into archived generation")
316		if err != nil {
317			return fmt.Errorf("failed to create merge commit: %w", err)
318		}
319	
320		// Update local archived ref and push it
321		newArchiveRef := plumbing.NewHashReference(archiveRefName, mergeCommitHash)
322		if err := repo.Storer.SetReference(newArchiveRef); err != nil {
323			return fmt.Errorf("failed to update archive ref: %w", err)
324		}
325	
326		if pushErr := tryPushRef(ctx, target, archiveRefName); pushErr != nil {
327			return fmt.Errorf("failed to push updated archive: %w", pushErr)
328		}
329	
330		// Adopt remote's /full/current as local
331		remoteRef, err := repo.Reference(tmpRefName, true)
332		if err != nil {
333			return fmt.Errorf("failed to get fetched /full/current: %w", err)
334		}
335		adoptedRef := plumbing.NewHashReference(refName, remoteRef.Hash())
336		if err := repo.Storer.SetReference(adoptedRef); err != nil {
337			return fmt.Errorf("failed to adopt remote /full/current: %w", err)
338		}
339	
340		return nil
341	}
342	
343	// updateGenerationTimestamps reads generation.json from a blob, updates
344	// newest_checkpoint_at if the provided newestFromLocal is newer, and returns
345	// an updated tree entry. Uses the local commit timestamp rather than
346	// time.Now() so cleanup scheduling reflects actual checkpoint creation time.
347	func updateGenerationTimestamps(repo *git.Repository, genBlobHash plumbing.Hash, newestFromLocal time.Time) (object.TreeEntry, error) {
348		blob, err := repo.BlobObject(genBlobHash)
349		if err != nil {
350			return object.TreeEntry{}, fmt.Errorf("failed to read generation blob: %w", err)
351		}
352		reader, err := blob.Reader()
353		if err != nil {
354			return object.TreeEntry{}, fmt.Errorf("failed to open generation blob reader: %w", err)
355		}
356		defer reader.Close()
357	
358		data, err := io.ReadAll(reader)
359		if err != nil {
360			return object.TreeEntry{}, fmt.Errorf("failed to read generation blob data: %w", err)
361		}
362	
363		var gen checkpoint.GenerationMetadata
364		if err := json.Unmarshal(data, &gen); err != nil {
365			return object.TreeEntry{}, fmt.Errorf("failed to parse generation.json: %w", err)
366		}
367	
368		if newestFromLocal.After(gen.NewestCheckpointAt) {
369			gen.NewestCheckpointAt = newestFromLocal
370		}
371	
372		updatedData, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
373		if err != nil {
374			return object.TreeEntry{}, fmt.Errorf("failed to marshal generation.json: %w", err)
375		}
376	
377		newBlobHash, err := checkpoint.CreateBlobFromContent(repo, updatedData)
378		if err != nil {
379			return object.TreeEntry{}, fmt.Errorf("failed to create generation blob: %w", err)
380		}
381	
382		return object.TreeEntry{
383			Name: paths.GenerationFileName,
384			Mode: filemode.Regular,
385			Hash: newBlobHash,
386		}, nil
387	}
388	
389	// pushV2Refs pushes v2 checkpoint refs to the target.
390	// Pushes /main, /full/current, and the latest archived generation (if any).
391	// Older archived generations are immutable and were pushed when created.
392	func pushV2Refs(ctx context.Context, target string) {
393		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2MainRefName))        //nolint:errcheck // pushRefIfNeeded handles errors internally
394		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullCurrentRefName)) //nolint:errcheck // pushRefIfNeeded handles errors internally
395	
396		// Push only the latest archived generation (most likely to be newly created)
397		repo, err := OpenRepository(ctx)
398		if err != nil {
399			return
400		}
401		store := checkpoint.NewV2GitStore(repo, ResolveCheckpointURL(ctx, "origin"))
402		archived, err := store.ListArchivedGenerations()
403		if err != nil || len(archived) == 0 {
404			return
405		}
406		latest := archived[len(archived)-1]
407		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullRefPrefix+latest)) //nolint:errcheck // pushRefIfNeeded handles errors internally
408	}
