410	// shortRefName returns a human-readable short form of a ref name for log output.
411	// e.g., "refs/entire/checkpoints/v2/main" -> "v2/main"
412	func shortRefName(refName plumbing.ReferenceName) string {
413		const prefix = "refs/entire/checkpoints/"
414		s := string(refName)
415		if strings.HasPrefix(s, prefix) {
416			return s[len(prefix):]
417		}
418		return s
419	}
